attributes.twig:
{
{# now contributors #}
{% set contributor_lod = [] %}
{% set agents_lod_accumulated_flat = [] %}
{% if data["pbcorecontributor"] is iterable and not empty %}
  {% for pbcorecontributor in data["pbcorecontributor"] %}
      {# Use to assign a contributorRole subelement when not present. #}
      {% set default_role = [{"@value": "Undefined"}] %}
      {% for role in pbcorecontributor.contributorRole|default(default_role) %}
       {% set role_uri = null %}
       {% if role['@value'] is not empty and role['@value'] != "Undefined" %}
          {% set role_uri  = "http://pbcore.org/pbcore-controlled-vocabularies/creatorrole-and-contributorrole-vocabulary/#" ~ role['@value'] %}
        {% endif %}
      {# Note: the agent type can't be really set from just the string #}
      {% set agent_type = null %}  
      {% if "radio" in pbcorecontributor.contributor[0]["@value"]|default("")|lower or "station" in pbcorecontributor.contributor[0]["@value"]|default("")|lower %}
          {% set agent_type = "corporate" %}  
        {% endif %}
      {% set contributor = {
             "name_uri":  pbcorecontributor.contributor[0]["@ref"]|default(""),
             "name_label": pbcorecontributor.contributor[0]["@value"],
             "agent_type": agent_type,
             "role_label": role['@value'],
             "role_uri": role_uri
       } %}
       {# we accumulate a joined name label and role label in contributor_lod_accumulated_flat as a dedup check. Faster than
       iterating over every element we already build again on every new entry #}
       {% if (contributor.name_label ~ "-" ~ contributor.role_label) not in agents_lod_accumulated_flat %}
         {% set contributor_lod = contributor_lod|merge([contributor]) %}
         {% set agents_lod_accumulated_flat = agents_lod_accumulated_flat|merge([contributor.name_label ~ "-" ~ contributor.role_label]) %}
       {% endif %}
     {% endfor %}
  {% endfor %}
{% endif %}
{% if contributor_lod is not empty %}
    "contributor_lod": {{ contributor_lod|json_encode|raw }}
{% endif %}
}
